package main

import (
	"fmt"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type Policy struct {
	DefaultAction string       `json:"default_action"`
	Rules         []PolicyRule `json:"rules"`
}

type PolicyRule struct {
	ID     string                 `json:"id"`
	Type   string                 `json:"type"`
	Params map[string]interface{} `json:"params"`
	Action string                 `json:"action"`
}

type policyEvaluation struct {
	PolicyOverallStatus   string            `json:"policy_overall_status"`
	DefaultAction         string            `json:"default_action"`
	RulesEvaluated        []policyRuleEval  `json:"rules_evaluated"`
	EffectiveStepStatuses map[string]string `json:"effective_step_statuses"`
	Warnings              []string          `json:"warnings"`
}

type policyRuleEval struct {
	RuleID        string   `json:"rule_id"`
	RuleType      string   `json:"rule_type"`
	MatchedSteps  []string `json:"matched_steps"`
	MatchedOutputs []string `json:"matched_outputs"`
	Action        string   `json:"action"`
	Effect        string   `json:"effect"`
	Details       string   `json:"details"`
}

var policyRuleIDRe = regexp.MustCompile(`^[a-z][a-z0-9_-]{0,63}$`)

func validatePolicy(p *Policy, stepIDs map[string]bool) error {
	if p == nil {
		return nil
	}
	if p.DefaultAction == "" {
		p.DefaultAction = "strict"
	}
	switch p.DefaultAction {
	case "strict", "lenient":
	default:
		return fmt.Errorf("invalid default_action: %q (must be \"strict\" or \"lenient\")", p.DefaultAction)
	}
	if p.Rules == nil {
		p.Rules = []PolicyRule{}
	}

	seenRuleIDs := map[string]bool{}
	for _, rule := range p.Rules {
		if !policyRuleIDRe.MatchString(rule.ID) {
			return fmt.Errorf("invalid policy rule id: %q (must match ^[a-z][a-z0-9_-]{0,63}$)", rule.ID)
		}
		if seenRuleIDs[rule.ID] {
			return fmt.Errorf("duplicate policy rule id: %q", rule.ID)
		}
		seenRuleIDs[rule.ID] = true

		switch rule.Action {
		case "allow", "warn", "require":
		default:
			return fmt.Errorf("invalid policy action: %q (must be \"allow\", \"warn\", or \"require\")", rule.Action)
		}

		switch rule.Type {
		case "allow_variance":
			if _, err := policyStringParam(rule, "output_pattern"); err != nil {
				return err
			}
		case "min_consistency_rate":
			if _, err := policyStringParam(rule, "step_pattern"); err != nil {
				return err
			}
			rate, err := policyFloatParam(rule, "rate")
			if err != nil {
				return err
			}
			if rate < 0.0 || rate > 1.0 {
				return fmt.Errorf("invalid min_consistency_rate: rate must be between 0.0 and 1.0")
			}
		case "required_steps":
			steps, err := policyStringSliceParam(rule, "steps")
			if err != nil {
				return err
			}
			for _, stepID := range steps {
				if !stepIDs[stepID] {
					return fmt.Errorf("unknown step in policy rule %q: %q", rule.ID, stepID)
				}
			}
		case "ignore_steps":
			steps, err := policyStringSliceParam(rule, "steps")
			if err != nil {
				return err
			}
			for _, stepID := range steps {
				if !stepIDs[stepID] {
					return fmt.Errorf("unknown step in policy rule %q: %q", rule.ID, stepID)
				}
			}
		default:
			return fmt.Errorf("unknown policy rule type: %q", rule.Type)
		}
	}
	return nil
}

func policyStringParam(rule PolicyRule, name string) (string, error) {
	v, ok := rule.Params[name]
	if !ok {
		return "", fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
	}
	s, ok := v.(string)
	if !ok {
		return "", fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
	}
	return s, nil
}

func policyFloatParam(rule PolicyRule, name string) (float64, error) {
	v, ok := rule.Params[name]
	if !ok {
		return 0, fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
	}
	f, ok := v.(float64)
	if !ok {
		return 0, fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
	}
	return f, nil
}

func policyStringSliceParam(rule PolicyRule, name string) ([]string, error) {
	v, ok := rule.Params[name]
	if !ok {
		return nil, fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
	}
	arr, ok := v.([]interface{})
	if !ok {
		return nil, fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
	}
	out := make([]string, 0, len(arr))
	for _, item := range arr {
		s, ok := item.(string)
		if !ok {
			return nil, fmt.Errorf("policy rule %q missing required param: %q", rule.ID, name)
		}
		out = append(out, s)
	}
	return out, nil
}

func evaluatePolicy(m *Manifest, rep *report) *policyEvaluation {
