					continue
				}
				if rawStatus[sr.ID] == "ERROR" || rawStatus[sr.ID] == "TIMEOUT" || rawStatus[sr.ID] == "SKIPPED" {
					continue
				}
				for _, o := range sr.Outputs {
					st := outputs[sr.ID][o.Path]
					if st == nil || st.matched {
						continue
					}
					matchedStepsAll[sr.ID] = true
					ev.MatchedSteps = appendUnique(ev.MatchedSteps, sr.ID)
					ev.MatchedOutputs = appendUnique(ev.MatchedOutputs, o.Path)
					st.matched = true

					majorityRate := majorityRate(o.Fingerprints)
					condition := majorityRate >= rate
					switch rule.Action {
					case "allow":
						if condition {
							st.effective = true
							ev.Effect = "applied"
							ev.Details = "output majority rate satisfies required consistency"
						}
					case "warn":
						if condition {
							warnings = append(warnings, fmt.Sprintf("rule %s: consistency allowed with warning for %s:%s", rule.ID, sr.ID, o.Path))
							ev.Effect = "applied"
							ev.Details = "warned about allowed consistency for matched outputs"
						}
					case "require":
						if !condition {
							requireViolation = true
							ev.Effect = "violation"
							ev.Details = fmt.Sprintf("majority rate %.3f below required %.3f", majorityRate, rate)
						} else {
							ev.Effect = "applied"
							ev.Details = "required majority rate satisfied"
						}
					}
				}
			}
			sort.Strings(ev.MatchedSteps)
			sort.Strings(ev.MatchedOutputs)
			ruleEvals = append(ruleEvals, ev)

		case "required_steps":
			ev := policyRuleEval{
				RuleID:   rule.ID,
				RuleType: rule.Type,
				Action:   rule.Action,
				Effect:   "not_applicable",
			}
			steps, _ := policyStringSliceParam(rule, "steps")
			ev.MatchedSteps = append([]string{}, steps...)
			sort.Strings(ev.MatchedSteps)
			for _, id := range steps {
				matchedStepsAll[id] = true
				if rule.Action == "require" {
					mustPassSteps[id] = true
				} else if rule.Action == "allow" {
					hasRequiredAllow = true
					requiredAllowListed[id] = true
				}
			}
			if rule.Action == "require" {
				ev.Effect = "applied"
				ev.Details = "listed steps are required to pass"
			} else if rule.Action == "allow" {
				ev.Effect = "applied"
				ev.Details = "unlisted steps are forgiven"
			}
			ruleEvals = append(ruleEvals, ev)

		case "ignore_steps":
			ev := policyRuleEval{
				RuleID:   rule.ID,
				RuleType: rule.Type,
				Action:   rule.Action,
				Effect:   "not_applicable",
			}
			steps, _ := policyStringSliceParam(rule, "steps")
			ev.MatchedSteps = append([]string{}, steps...)
			sort.Strings(ev.MatchedSteps)
			for _, id := range steps {
				matchedStepsAll[id] = true
				ignoredSteps[id] = true
			}
			if len(steps) > 0 {
				ev.Effect = "applied"
				ev.Details = "steps ignored from policy evaluation"
			}
			ruleEvals = append(ruleEvals, ev)
		}
	}

	effectiveStatus := map[string]string{}
	for _, sr := range rep.Steps {
		id := sr.ID
		st := rawStatus[id]
		if st == "ERROR" || st == "TIMEOUT" || st == "SKIPPED" {
			effectiveStatus[id] = st
			continue
		}
		badOutput := false
		for _, o := range sr.Outputs {
			if outputs[id][o.Path] != nil && !outputs[id][o.Path].effective {
				badOutput = true
				break
			}
		}
		if badOutput {
			effectiveStatus[id] = "FAIL"
		} else {
			effectiveStatus[id] = "PASS"
		}
	}

	policyStatus := "PASS"
	for _, sr := range rep.Steps {
		id := sr.ID
		if ignoredSteps[id] {
			continue
		}
		relevant := true
		if hasRequiredAllow && !requiredAllowListed[id] && !mustPassSteps[id] {
			relevant = false
		}
		if !relevant {
			continue
		}
		if effectiveStatus[id] == "ERROR" || effectiveStatus[id] == "TIMEOUT" {
			policyStatus = "ERROR"
			break
		}
	}
	if policyStatus != "ERROR" {
		if requireViolation {
			policyStatus = "FAIL"
		} else {
			for _, sr := range rep.Steps {
				id := sr.ID
				if ignoredSteps[id] {
					continue
				}
				relevant := true
				if hasRequiredAllow && !requiredAllowListed[id] && !mustPassSteps[id] {
					relevant = false
				}
				if !relevant {
					continue
				}
				if mustPassSteps[id] && effectiveStatus[id] != "PASS" {
					policyStatus = "FAIL"
					break
				}
				if defaultAction == "strict" && effectiveStatus[id] == "FAIL" {
					policyStatus = "FAIL"
					break
				}
			}
		}
	}

	effectiveStepStatuses := map[string]string{}
	for _, sr := range rep.Steps {
		id := sr.ID
		if matchedStepsAll[id] || effectiveStatus[id] != rawStatus[id] {
			effectiveStepStatuses[id] = effectiveStatus[id]
		}
	}

	return &policyEvaluation{
		PolicyOverallStatus:   policyStatus,
		DefaultAction:         defaultAction,
		RulesEvaluated:        ruleEvals,
		EffectiveStepStatuses: effectiveStepStatuses,
		Warnings:              warnings,
	}
}

func majorityRate(fps []string) float64 {
	if len(fps) == 0 {
		return 0
	}
	counts := map[string]int{}
	for _, fp := range fps {
		counts[fp]++
	}
	max := 0
	for _, c := range counts {
		if c > max {
			max = c
		}
	}
	return float64(max) / float64(len(fps))
}

func appendUnique(slice []string, value string) []string {
	for _, v := range slice {
		if v == value {
			return slice
		}
	}
	return append(slice, value)
}

func boolPtr(b bool) *bool {
	return &b
}

func stringSlicePtr(s []string) *[]string {
	if s == nil {
		return nil
	}
	return &s
}
