)

type diffReport struct {
	Baseline           diffReportMeta    `json:"baseline"`
	Current            diffReportMeta    `json:"current"`
	ComparisonTimestamp string             `json:"comparison_timestamp"`
	StatusTransition   diffStatusTransition `json:"status_transition"`
