type diffOutputDetail struct {
	BaselineFingerprints  []string `json:"baseline_fingerprints"`
	CurrentFingerprints   []string `json:"current_fingerprints"`
	BaselineConsistent    *bool    `json:"baseline_consistent"`
	CurrentConsistent     *bool    `json:"current_consistent"`
	BaselineReferenceMatch *bool   `json:"baseline_reference_match"`
	CurrentReferenceMatch  *bool   `json:"current_reference_match"`
}

type diffSummary struct {
	StepsAdded       int `json:"steps_added"`
	StepsRemoved     int `json:"steps_removed"`
	StepsModified    int `json:"steps_modified"`
	StepsUnchanged   int `json:"steps_unchanged"`
	Regressions      int `json:"regressions"`
	Improvements     int `json:"improvements"`
	TotalOutputChanges int `json:"total_output_changes"`
}

type diffReportLite struct {
	ManifestName    string `json:"manifest_name"`
	ManifestVersion string `json:"manifest_version"`
	OverallStatus   string `json:"overall_status"`
	Timestamp       string `json:"timestamp"`
	Steps           []stepReport `json:"steps"`
}

func diffCmd(args []string) {
	format := "json"
	positional := parseFlags(args, map[string]*string{
		"format": &format,
	})
	if len(positional) != 2 {
		fmt.Fprintln(os.Stderr, "usage: repro-verify diff <baseline.json> <current.json> [--format json|text]")
		os.Exit(2)
	}

	baseline, err := loadDiffReport(positional[0], "baseline")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}
	current, err := loadDiffReport(positional[1], "current")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(2)
	}

	diff := buildDiffReport(baseline, current)

	if format == "text" {
		printDiffText(diff)
	} else {
		out, err := json.MarshalIndent(diff, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			os.Exit(2)
		}
		fmt.Println(string(out))
	}

	if diff.Summary.Regressions > 0 {
		os.Exit(1)
	}
	os.Exit(0)
}

func loadDiffReport(path, role string) (*diffReportLite, error) {
	if _, err := os.Stat(path); err != nil {
		if os.IsNotExist(err) {
			return nil, fmt.Errorf("error: diff %s not found: %s", role, path)
		}
		return nil, fmt.Errorf("error: invalid report: %s: %s", path, err)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("error: invalid report: %s: %s", path, err)
	}
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("error: invalid report: %s: %s", path, err)
	}
	for _, field := range []string{"manifest_name", "overall_status", "steps"} {
		if _, ok := raw[field]; !ok {
			return nil, fmt.Errorf("error: invalid report: %s: missing field %s", path, field)
		}
	}
	var r diffReportLite
	if err := json.Unmarshal(data, &r); err != nil {
		return nil, fmt.Errorf("error: invalid report: %s: %s", path, err)
	}
	if r.ManifestName == "" {
		return nil, fmt.Errorf("error: invalid report: %s: missing field manifest_name", path)
	}
	if r.OverallStatus == "" {
		return nil, fmt.Errorf("error: invalid report: %s: missing field overall_status", path)
	}
	if r.Steps == nil {
		r.Steps = []stepReport{}
	}
	return &r, nil
}

func buildDiffReport(baseline, current *diffReportLite) *diffReport {
	baselineSteps := map[string]stepReport{}
	for _, s := range baseline.Steps {
		baselineSteps[s.ID] = s
	}
	currentSteps := map[string]stepReport{}
	for _, s := range current.Steps {
		currentSteps[s.ID] = s
	}

	stepIDs := map[string]bool{}
	for id := range baselineSteps {
		stepIDs[id] = true
	}
	for id := range currentSteps {
		stepIDs[id] = true
	}

	ids := make([]string, 0, len(stepIDs))
	for id := range stepIDs {
		ids = append(ids, id)
	}
	sort.Strings(ids)

	changes := make([]diffStepChange, 0, len(ids))
	summary := diffSummary{}

	for _, id := range ids {
		b, hasB := baselineSteps[id]
		c, hasC := currentSteps[id]

		change := diffStepChange{
			StepID: id,
		}
		if hasB {
			bs := b.Status
			change.BaselineStatus = &bs
		}
		if hasC {
			cs := c.Status
			change.CurrentStatus = &cs
		}

		switch {
		case hasC && !hasB:
			change.ChangeType = "added"
			summary.StepsAdded++
			summary.TotalOutputChanges += len(c.Outputs)
		case hasB && !hasC:
			change.ChangeType = "removed"
			summary.StepsRemoved++
			summary.TotalOutputChanges += len(b.Outputs)
		default:
			outputChanges, outputChanged := diffStepOutputs(b, c)
			change.OutputChanges = outputChanges
			if outputChanged || !stepEqual(b, c) {
				change.ChangeType = "modified"
				summary.StepsModified++
			} else {
				change.ChangeType = "unchanged"
				summary.StepsUnchanged++
				change.OutputChanges = []diffOutputChange{}
			}
			for _, oc := range outputChanges {
				if oc.ChangeType != "unchanged" {
					summary.TotalOutputChanges++
				}
			}
		}

		if hasB && hasC && b.Status != c.Status {
			tr := statusTransitionType(b.Status, c.Status)
			change.StatusTransition = &tr
			if tr == "regression" {
				summary.Regressions++
			} else if tr == "improvement" {
				summary.Improvements++
			}
		}

		changes = append(changes, change)
	}

	return &diffReport{
		Baseline: diffReportMeta{
			ManifestName:    baseline.ManifestName,
			ManifestVersion: baseline.ManifestVersion,
			OverallStatus:   baseline.OverallStatus,
			Timestamp:       baseline.Timestamp,
		},
		Current: diffReportMeta{
			ManifestName:    current.ManifestName,
			ManifestVersion: current.ManifestVersion,
			OverallStatus:   current.OverallStatus,
			Timestamp:       current.Timestamp,
		},
		ComparisonTimestamp: time.Now().UTC().Format(time.RFC3339),
		StatusTransition: diffStatusTransition{
			From: baseline.OverallStatus,
			To:   current.OverallStatus,
			Type: statusTransitionType(baseline.OverallStatus, current.OverallStatus),
		},
		StepChanges: changes,
		Summary:     summary,
	}
}

func diffStepOutputs(b, c stepReport) ([]diffOutputChange, bool) {
	bOutputs := map[string]outputReport{}
	for _, o := range b.Outputs {
		bOutputs[o.Path] = o
	}
	cOutputs := map[string]outputReport{}
	for _, o := range c.Outputs {
		cOutputs[o.Path] = o
	}

	paths := map[string]bool{}
	for p := range bOutputs {
		paths[p] = true
	}
	for p := range cOutputs {
		paths[p] = true
	}

	var keys []string
	for p := range paths {
		keys = append(keys, p)
	}
	sort.Strings(keys)

	changes := []diffOutputChange{}
	changed := false

	for _, p := range keys {
		bo, hasB := bOutputs[p]
		co, hasC := cOutputs[p]

		oc := diffOutputChange{
			Path: p,
			Details: diffOutputDetail{
				BaselineFingerprints:   nilIfEmpty(bo.Fingerprints),
				CurrentFingerprints:    nilIfEmpty(co.Fingerprints),
			},
		}
		if hasB {
			oc.Details.BaselineConsistent = &bo.CrossPassConsistent
			if bo.ReferenceMatch != nil {
				oc.Details.BaselineReferenceMatch = bo.ReferenceMatch
			}
		}
		if hasC {
			oc.Details.CurrentConsistent = &co.CrossPassConsistent
			if co.ReferenceMatch != nil {
				oc.Details.CurrentReferenceMatch = co.ReferenceMatch
			}
		}

		switch {
		case hasC && !hasB:
			oc.ChangeType = "added"
			changed = true
		case hasB && !hasC:
			oc.ChangeType = "removed"
			changed = true
		case !equalStrings(bo.Fingerprints, co.Fingerprints):
			oc.ChangeType = "fingerprint_changed"
			changed = true
		case bo.CrossPassConsistent != co.CrossPassConsistent:
			oc.ChangeType = "consistency_changed"
			changed = true
		case !boolPtrEqual(bo.ReferenceMatch, co.ReferenceMatch):
			oc.ChangeType = "reference_changed"
			changed = true
		default:
			oc.ChangeType = "unchanged"
		}
		changes = append(changes, oc)
	}

	return changes, changed
}

func stepEqual(b, c stepReport) bool {
	if b.Status != c.Status || b.ExecutionOrder != c.ExecutionOrder || b.ErrorMessage != c.ErrorMessage {
		return false
	}
	if !equalStrings(b.TimingMs, c.TimingMs) {
		return false
	}
	if len(b.Outputs) != len(c.Outputs) {
		return false
	}
	for i := range b.Outputs {
		if !outputEqual(b.Outputs[i], c.Outputs[i]) {
			return false
		}
	}
	return true
}

func outputEqual(b, c outputReport) bool {
	if b.Path != c.Path {
		return false
	}
	if !equalStrings(b.Fingerprints, c.Fingerprints) {
		return false
	}
	if b.CrossPassConsistent != c.CrossPassConsistent {
		return false
	}
	if !boolPtrEqual(b.ReferenceMatch, c.ReferenceMatch) {
		return false
	}
	if !stringPtrEqual(b.Reference, c.Reference) {
		return false
	}
	if !stringPtrEqual(b.VarianceDetail, c.VarianceDetail) {
		return false
	}
	return true
}

func statusTransitionType(from, to string) string {
	rank := func(s string) int {
		switch s {
		case "PASS":
			return 4
		case "FAIL":
			return 3
		case "ERROR":
			return 2
		case "TIMEOUT":
			return 1
		case "SKIPPED":
			return 0
		default:
			return -1
		}
	}
	r := rank(to) - rank(from)
	switch {
		case r < 0:
			return "regression"
		case r > 0:
			return "improvement"
		default:
			return "unchanged"
	}
}

func nilIfEmpty(s []string) []string {
	if len(s) == 0 {
		return nil
	}
	return s
}

func equalStrings(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func boolPtrEqual(a, b *bool) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	return *a == *b
}

func stringPtrEqual(a, b *string) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	return *a == *b
}

func printDiffText(d *diffReport) {
	fmt.Println("Verification Report Diff")
	fmt.Println("========================")
	fmt.Printf("Baseline: %s@%s (%s) at %s\n", d.Baseline.ManifestName, d.Baseline.ManifestVersion, d.Baseline.OverallStatus, d.Baseline.Timestamp)
	fmt.Printf("Current:  %s@%s (%s) at %s\n", d.Current.ManifestName, d.Current.ManifestVersion, d.Current.OverallStatus, d.Current.Timestamp)
	fmt.Printf("Overall:  %s → %s [%s]\n", d.StatusTransition.From, d.StatusTransition.To, d.StatusTransition.Type)
	fmt.Println()
	fmt.Println("Step Changes:")
	for _, sc := range d.StepChanges {
		switch sc.ChangeType {
		case "added":
			status := ""
			if sc.CurrentStatus != nil {
				status = *sc.CurrentStatus
			}
			fmt.Printf("  + %s [%s]\n", sc.StepID, status)
		case "removed":
			status := ""
			if sc.BaselineStatus != nil {
				status = *sc.BaselineStatus
			}
			fmt.Printf("  - %s [%s]\n", sc.StepID, status)
		case "modified":
			if sc.BaselineStatus != nil && sc.CurrentStatus != nil {
				fmt.Printf("  ~ %s [%s → %s]\n", sc.StepID, *sc.BaselineStatus, *sc.CurrentStatus)
			} else {
				fmt.Printf("  ~ %s\n", sc.StepID)
			}
			for _, oc := range sc.OutputChanges {
				fmt.Printf("    Output: %s — %s\n", oc.Path, oc.ChangeType)
			}
		case "unchanged":
			fmt.Printf("  = %s\n", sc.StepID)
		}
	}
	fmt.Println()
	fmt.Printf("Summary: %d added, %d removed, %d modified, %d unchanged\n",
		d.Summary.StepsAdded, d.Summary.StepsRemoved, d.Summary.StepsModified, d.Summary.StepsUnchanged)
	fmt.Printf("         %d regressions, %d improvements\n",
		d.Summary.Regressions, d.Summary.Improvements)
}
